import { renderHook } from '@testing-library/react-hooks';
import userEvent from '@testing-library/user-event';
import { useOnClickOutside } from './useOnClickOutside';

describe('useOnClickOutside', () => {
  const ref = { current: document.createElement('div') };
  const handler = jest.fn();

  beforeEach(() => jest.clearAllMocks());

  it('should call the handler function when a click event occurs outside the ref', async () => {
    renderHook(() => useOnClickOutside(ref, handler));
    await userEvent.click(document.body);
    expect(handler).toHaveBeenCalled();
  });

  it('should not call the handler function when a click event occurs inside the ref', async () => {
    renderHook(() => useOnClickOutside(ref, handler));
    await userEvent.click(ref.current);
    expect(handler).not.toHaveBeenCalled();
  });
});
